questions.question_text:
Find the area of the shaded region between $y=3x$ and $y=x^{2}$ from $x=1$ to $x=2$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.5cm, y=0.55cm]
\fill[gray!35] (1,1) -- plot[domain=1:2, samples=2, variable=\x] ({\x},{3*\x}) -- plot[domain=2:1, samples=60, variable=\x] ({\x},{\x*\x}) -- cycle;
\draw[->] (-0.7,0) -- (3.1,0) node[right] {$x$};
\draw[->] (0,-1.4) -- (0,9.4) node[above] {$y$};
\draw[thick, <->, domain=-0.5:2.8, samples=2, variable=\x] plot ({\x},{3*\x}) node[pos=0.98, right] {$y=3x$};
\draw[thick, <->, domain=-0.5:2.9, samples=60, variable=\x] plot ({\x},{\x*\x}) node[pos=0.98, below right] {$y=x^{2}$};
\node[below] at (1,-0.2) {$1$};
\node[below] at (2,-0.2) {$2$};
\end{tikzpicture}
[/tikz]

Find the area of the shaded region enclosed by $y=2x+3$ and $y=x^{2}$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.85cm, y=0.45cm]
\fill[gray!35] (-1,1) -- plot[domain=-1:3, samples=2, variable=\x] ({\x},{2*\x+3}) -- plot[domain=3:-1, samples=60, variable=\x] ({\x},{\x*\x}) -- cycle;
\draw[->] (-2.8,0) -- (3.8,0) node[right] {$x$};
\draw[->] (0,-2.4) -- (0,11.6) node[above] {$y$};
\draw[thick, <->, domain=-2.2:3.4, samples=2, variable=\x] plot ({\x},{2*\x+3}) node[pos=0.98, below right] {$y=2x+3$};
\draw[thick, <->, domain=-2.3:3.2, samples=60, variable=\x] plot ({\x},{\x*\x}) node[pos=0.98, right] {$y=x^{2}$};
\end{tikzpicture}
[/tikz]

Find the total area of the two shaded regions between $y=4x$ and $y=x^{2}$ from $x=0$ to $x=5$.
[tikz]\begin{tikzpicture}[every node/.style={font=\large}, x=0.75cm, y=0.2cm]
\fill[gray!35] (0,0) -- plot[domain=0:4, samples=2, variable=\x] ({\x},{4*\x}) -- plot[domain=4:0, samples=60, variable=\x] ({\x},{\x*\x}) -- cycle;
\fill[gray!35] (4,16) -- plot[domain=4:5, samples=60, variable=\x] ({\x},{\x*\x}) -- plot[domain=5:4, samples=2, variable=\x] ({\x},{4*\x}) -- cycle;
\draw[->] (-1.2,0) -- (6.4,0) node[right] {$x$};
\draw[->] (0,-3) -- (0,28) node[above] {$y$};
\draw[thick, <->, domain=-0.6:6, samples=2, variable=\x] plot ({\x},{4*\x});
\draw[thick, <->, domain=-1:5.1, samples=60, variable=\x] plot ({\x},{\x*\x});
\node at (2.4,23) {$y=x^{2}$};
\node at (6.6,19) {$y=4x$};
\node[below] at (5,-1.2) {$5$};
\end{tikzpicture}[/tikz]

Find the area of the shaded region bounded by $y=x^{2}$, $y=(x-4)^{2}$ and the $x$-axis.
[tikz]\begin{tikzpicture}[every node/.style={font=\large}, x=1.1cm, y=1cm]
\fill[gray!35] (0,0) -- plot[domain=0:2, samples=60, variable=\x] ({\x},{\x*\x}) -- (2,0) -- cycle;
\fill[gray!35] (2,0) -- plot[domain=2:4, samples=60, variable=\x] ({\x},{(\x-4)*(\x-4)}) -- cycle;
\draw[->] (-0.8,0) -- (5.2,0) node[right] {$x$};
\draw[->] (0,-0.7) -- (0,5.8) node[above] {$y$};
\draw[thick, <->, domain=-0.5:2.3, samples=60, variable=\x] plot ({\x},{\x*\x});
\draw[thick, <->, domain=1.7:4.8, samples=60, variable=\x] plot ({\x},{(\x-4)*(\x-4)});
\node at (0.92,3.6) {$y=x^{2}$};
\node at (4.1,3.0) {$y=(x-4)^{2}$};
\node[below] at (4,-0.15) {$4$};
\end{tikzpicture}[/tikz]

Find the area of the shaded region between $y=2-x^{2}$ and $y=-2$ from $x=0$ to $x=1$.
[tikz]\begin{tikzpicture}[every node/.style={font=\large}, x=1cm, y=0.9cm]
\fill[gray!35] (0,-2) -- plot[domain=0:1, samples=60, variable=\x] ({\x},{2-\x*\x}) -- plot[domain=1:0, samples=2, variable=\x] ({\x},{-2}) -- cycle;
\draw[->] (-2.8,0) -- (2.8,0) node[right] {$x$};
\draw[->] (0,-3.2) -- (0,3.2) node[above] {$y$};
\draw[thick, <->, domain=-2.2:2.2, samples=60, variable=\x] plot ({\x},{2-\x*\x});
\draw[thick, <->, domain=-2.4:2.4, samples=2, variable=\x] plot ({\x},{-2});
\node at (-1.6,2.4) {$y=2-x^{2}$};
\node at (-1.2,-2.55) {$y=-2$};
\end{tikzpicture}[/tikz]

The horizontal line $y=k$, where $k>0$, cuts the parabola $y=x^{2}$ so that the enclosed shaded region has area $\dfrac{500}{3}\ \text{units}^{2}$.
Find $k$.
[tikz]\begin{tikzpicture}[every node/.style={font=\large}, x=0.62cm, y=0.38cm]
\fill[gray!35] (-2.83,8) -- plot[domain=-2.83:2.83, samples=2, variable=\x] ({\x},{8}) -- plot[domain=2.83:-2.83, samples=60, variable=\x] ({\x},{\x*\x}) -- cycle;
\draw[->] (-4.4,0) -- (4.4,0) node[right] {$x$};
\draw[->] (0,-2.2) -- (0,13.6) node[above] {$y$};
\draw[thick, <->, domain=-4:4, samples=2, variable=\x] plot ({\x},{8});
\draw[thick, <->, domain=-3.5:3.5, samples=60, variable=\x] plot ({\x},{\x*\x});
\node at (1.4,9.1) {$y=k$};
\node at (-1.7,11.6) {$y=x^{2}$};
\end{tikzpicture}[/tikz]

Find the exact area of the shaded region between $y=e^{x}$ and $y=1$ from $x=0$ to $x=2$.
[tikz]\begin{tikzpicture}[every node/.style={font=\large}, x=1.2cm, y=0.55cm]
\fill[gray!35] (0,1) -- plot[domain=0:2, samples=60, variable=\x] ({\x},{exp(\x)}) -- plot[domain=2:0, samples=2, variable=\x] ({\x},{1}) -- cycle;
\draw[->] (-1.8,0) -- (2.8,0) node[right] {$x$};
\draw[->] (0,-1.2) -- (0,8.8) node[above] {$y$};
\draw[thick, <->, domain=-1.5:2.1, samples=80, variable=\x] plot ({\x},{exp(\x)});
\draw[thick, <->, domain=-1.6:2.6, samples=2, variable=\x] plot ({\x},{1});
\node at (1.0,7.0) {$y=e^{x}$};
\node at (-1.0,1.75) {$y=1$};
\node[below] at (2,-0.25) {$2$};
\end{tikzpicture}[/tikz]
